records.logicalInterface:
function Call(index: nat, target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>,
                env: R.Environment, history: seq<R.Request>): Outcome
    requires |selector| == 4

function Probe(target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>, expected: seq<Byte>,
                 env: R.Environment, history: seq<R.Request>): Outcome
    requires |selector| == 4 && |expected| == 4

lemma Outcomes(data: seq<Byte>, parameters: seq<seq<Byte>>, self: R.Address, decode: seq<Byte>->M.Decode,
                 env: R.Environment, history: seq<R.Request>)
    requires decode(data).Decoded? ==> M.Wire(decode(data).graph,parameters)
    ensures decode(data).Malformed? ==> M.Spec(data,parameters,self,decode,env,history) == M.Outcome(E.Aborted(E.Error([])),history)
    ensures decode(data).Decoded? ==>
              M.Spec(data,parameters,self,decode,env,history).history == history+[R.Call(self,M.CallData(decode(data).graph,parameters))]
    ensures decode(data).Decoded? ==>
              var callData := M.CallData(decode(data).graph,parameters);
              var observed := env.call(history,R.Call(self,callData));
              var raw := M.Spec(data,parameters,self,decode,env,history).raw;
              raw == (if !observed.codePresent then E.Aborted(E.Error(W.Encoded(C.InvalidTarget(0,self))))
                      else if observed.success then E.Produced(observed.data)
                      else if R.Exhausted(observed) then E.Aborted(E.Error(R.Signal()))
                      else E.Aborted(E.Error(W.Encoded(C.NodeCallFailed(0,self,callData,observed.data)))))

datatype Inner = NoGraph | Evaluated(out: Entry.Outcome, raw: E.Raw,
                                       evidence: M.Evidence, guards: seq<Guards.Record>)

  // One explicit modeled self-call observation connects the already-proved
  // encoded source wrapper to the public graph evaluation. Gas is observed,
  // and caller/static/memory projections remain separate EVM premises.

method CallReceipt(index: nat, target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>,
                     env: R.Environment, history: seq<R.Request>) returns (ghost raw: E.Raw, after: seq<R.Request>)
    requires |selector| == 4 && index < Pow256(32)
    ensures after == C.Call(index,target,self,data,selector,env,history).history
    ensures var result := C.Call(index,target,self,data,selector,env,history).result;
            if result.Returned? then raw == E.Produced(result.data)
            else raw == E.Aborted(E.Error(W.Spec(result.error)))

method ProbeReceipt(target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>, expected: seq<Byte>,
                      env: R.Environment, history: seq<R.Request>) returns (ghost raw: E.Raw, after: seq<R.Request>)
    requires |selector| == 4 && |expected| == 4
    requires |env.call(history,R.Call(target,data)).data|+96 < Pow256(32)
    ensures after == C.Probe(target,self,data,selector,expected,env,history).history
    ensures var result := C.Probe(target,self,data,selector,expected,env,history).result;
            if result.Returned? then raw == E.Produced(Encode(Bytes,Buffer(result.data)))
            else raw == E.Aborted(E.Error(W.Spec(result.error)))
    ensures raw.Produced? ==> Validate(Bytes,ExpressionEvaluationBridge.Narrow(raw.value)).Parsed?
